// editor/commands.ts — Shared ProseMirror commands (共享 PM 命令)
// 纯函数层，零 React 依赖。Toolbar 和 MenuBar 共用。
// Reference: .dev/plan/implementation-plan.md §Phase 2

import {
  alignCenter,
  alignJustify,
  alignLeft,
  alignRight,
  applyTableStyle,
  clearFontFamily,
  clearFontSize,
  clearHighlight,
  clearTextColor,
  createRemoveMarkCommand,
  createSetMarkCommand,
  insertTable,
  mergeCells,
  setCellBorder,
  setCellFillColor,
  setCellVerticalAlign,
  setFontFamily,
  setFontSize,
  setHighlight,
  setImageWrapType,
  setRowHeight,
  setTableProperties,
  setTextColor,
  splitCell,
  toggleHeaderRow,
} from "@eigenpal/docx-editor-core/prosemirror/commands";
import { open } from "@tauri-apps/plugin-dialog";
import { lift, setBlockType, toggleMark, wrapIn } from "prosemirror-commands";
import { redo, undo } from "prosemirror-history";
import { liftListItem, sinkListItem } from "prosemirror-schema-list";
import type { Command } from "prosemirror-state";
import type { EditorView } from "prosemirror-view";
import type { Alignment } from "@/features/formatting/constants";
import { useDocumentStore } from "@/stores/useDocumentStore";

// === 内部获取 EditorView ===

function getView(): EditorView | null {
  const bridge = useDocumentStore.getState().editorBridge;
  if (!bridge) {
    return null;
  }
  return bridge.getEditorView() as EditorView | null;
}

function dispatch(view: EditorView, cmd: Command): void {
  const { state, dispatch: viewDispatch } = view;
  cmd(state, viewDispatch);
}

function apply(cmd: Command): void {
  const view = getView();
  if (view) {
    dispatch(view, cmd);
  }
}
/**
 * 批量应用命令(单事务,一次 undo)/ Apply commands in a single transaction.
 *
 * 在单个累积 transaction 上追加所有命令产生的 step,仅 dispatch 一次,
 * 避免一次格式刷应用产生 15+ 个 undo step。每个命令接收"前一命令应用后的 state"
 * 与一个把 innerTr.steps 追加到累积 tr 的 dispatch 回调。
 *
 * 注意:ProseMirror Transform 没有 append(innerTr) 方法,只能逐个 tr.step(step)。
 * innerTr 由当前 state 构建,其 steps 与累积 tr 的当前文档兼容。

